1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type Step = {
9	  op: string;
10	  items?: Item[];
11	};
12	
13	export type Scenario = {
14	  customer: { yearsWithMHPCO: number };
15	  steps: Step[];
16	};
17	
18	export type StepResult = { premium: number };
19	
20	export type ScenarioResult = { results: StepResult[] };
21	
22	const BASE_PRICE_BY_TYPE: Record<string, number> = {
23	  sword: 100,
24	  amulet: 60,
25	  staff: 80,
26	  potion: 40,
27	  rune: 25,
28	  moonstone: 25,
29	};
30	
31	const FIRST_INSURANCE_MULTIPLIER = 1.1;
32	const CONTRACT_FEE = 5;
33	
34	const BUILDING_BLOCK_SIZE = 3;
35	const BUILDING_BLOCK_BASE_PRICE = 60;
36	
37	const CURSED_MULTIPLIER = 1.5;
38	const HIGH_ENCHANTMENT_LEVEL = 5;
39	const HIGH_ENCHANTMENT_MULTIPLIER = 1.3;
40	
41	// Each surcharge multiplies the base price when its condition holds. They
42	// compose multiplicatively, so an item matching several pays all of them.
43	const RISK_SURCHARGES: { appliesTo: (item: Item) => boolean; multiplier: number }[] = [
44	  { appliesTo: (item) => item.cursed === true, multiplier: CURSED_MULTIPLIER },
45	  {
46	    appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL,
47	    multiplier: HIGH_ENCHANTMENT_MULTIPLIER,
48	  },
49	];
50	
51	// Risk surcharges apply per item, before the contract-level multiplier and fee.
52	const riskAdjustedPriceOfItem = (item: Item): number =>
53	  RISK_SURCHARGES.reduce(
54	    (price, surcharge) =>
55	      surcharge.appliesTo(item) ? price * surcharge.multiplier : price,
56	    BASE_PRICE_BY_TYPE[item.type],
57	  );
58	
59	const sumOfIndividualPrices = (items: Item[]): number =>
60	  items.reduce((total, item) => total + riskAdjustedPriceOfItem(item), 0);
61	
62	// "Alike" in the price list means same type — material and enchantment do not
63	// affect whether components group into a building block.
64	const groupByType = (items: Item[]): Item[][] => {
65	  const groups = new Map<string, Item[]>();
66	
67	  for (const item of items) {
68	    const group = groups.get(item.type);
69	    if (group) group.push(item);
70	    else groups.set(item.type, [item]);
71	  }
72	
73	  return [...groups.values()];
74	};
75	
76	// Every three alike components form a building block priced at 60 G; the
77	// remainder of the group is priced individually.
78	const basePriceOfAlikeGroup = (group: Item[]): number => {
79	  const blocks = Math.floor(group.length / BUILDING_BLOCK_SIZE);
80	  const leftovers = group.slice(blocks * BUILDING_BLOCK_SIZE);
81	
82	  return blocks * BUILDING_BLOCK_BASE_PRICE + sumOfIndividualPrices(leftovers);
83	};
84	
85	const basePriceOf = (items: Item[]): number =>
86	  groupByType(items).reduce(
87	    (total, group) => total + basePriceOfAlikeGroup(group),
88	    0,
89	  );
90	
91	// Math.round only clears the float artifact in 100 × 1.1 = 110.00000000000001;
92	// no test yet lands on a half-way value, so the rounding *direction* stays
93	// unspecified until the "rounds in MHPCO's favor" test pins it.
94	const quoteStep = (step: Step): StepResult => ({
95	  premium:
96	    Math.round(basePriceOf(step.items!) * FIRST_INSURANCE_MULTIPLIER) + CONTRACT_FEE,
97	});
98	
99	export const runScenario = (scenario: Scenario): ScenarioResult => ({
100	  results: scenario.steps.map(quoteStep),
101	});
